        10: seg = 127;
        11: seg = 127;
        12: seg = 127;
        13: seg = 127;
        14: seg = 127;
        default: seg = 127;
    endcase
end


always @(reloj_core0_sel, reloj_core0_beep) begin: reloj_core0_punto
    if (((reloj_core0_sel == 2) && reloj_core0_beep)) begin
        dp = 0;
    end
    else begin
        dp = 1;
    end
end



assign rst = (!rst_n);



assign audio_sd = rst_n;

endmodule
